"""Step 3+4: Recursive clustering taxonomy + discriminative naming."""
import json, pickle, re
import numpy as np
import pandas as pd
from collections import defaultdict, Counter
from sklearn.cluster import KMeans
from sklearn.metrics import silhouette_score

RNG = 42
MIN_SPLIT = 14      # nodes smaller than this become leaves (no deeper level)
MIN_CHILD = 4       # desired min avg members per child
COVER_TARGET = 0.70 # representativeness target for a node name

data = pd.read_pickle("/root/work/data.pkl")
EMB = np.load("/root/work/emb.npy")
N = len(data)
emb_idx = data["emb_idx"].to_numpy()
orig_depth = data["orig_depth"].to_numpy()
lemma_levels = data["lemma_levels"].tolist()
X = EMB[emb_idx]    # per-item embedding (N x d)

STOP = {"and","the","of","for","with","other","others","misc","miscellaneous",
        "general","all","more","item","items","product","products","type","types",
        "n","a","s","to","in","by","amp","etc","set","sets","kit","kits","new","supply"}

ACRONYM = {"tv","cd","dvd","usb","gps","atv","rv","pc","led","lcd","hd","ac","dc",
           "suv","dj","vr","3d","cpu","gpu","ssd","rc","tt","mp3","uv","ph","id"}

def title_word(w):
    if w in ACRONYM:
        return w.upper()
    return w.capitalize()

def fmt_name(words):
    return " | ".join(title_word(w) for w in words)

def node_tokens(member_idx, level):
    """Per-member set of lemma tokens from this level and deeper (granularity-aware)."""
    out = []
    for it in member_idx:
        toks = set()
        for lv in lemma_levels[it][level-1:]:
            for w in lv:
                if w not in STOP and not w.isdigit():
                    toks.add(w)
        if not toks:  # granularity-capped item: fall back to its deepest available level
            for lv in lemma_levels[it]:
                for w in lv:
                    if w not in STOP and not w.isdigit():
                        toks.add(w)
        out.append(toks)
    return out

def coverage_map(token_sets):
    n = len(token_sets)
    c = Counter()
    for ts in token_sets:
        for w in ts:
            c[w] += 1
    return {w: cnt / n for w, cnt in c.items()}, n

def union_coverage(token_sets, words):
    if not words:
        return 0.0
    wset = set(words)
    hit = sum(1 for ts in token_sets if ts & wset)
    return hit / len(token_sets)

def choose_K(idx, level):
    n = len(idx)
    kmin = 10 if level == 1 else 3
    kmax = 20
    kmax = min(kmax, n // MIN_CHILD)
    if kmax < kmin:
        if level == 1:
            kmax = max(kmin, kmax)  # force at least kmin at root
        else:
            return None
    if kmax < kmin:
        return None
    Xs = X[idx]
    # subsample for silhouette speed
    if n > 2500:
        rs = np.random.RandomState(RNG)
        sub = rs.choice(n, 2500, replace=False)
    else:
        sub = np.arange(n)
    best_k, best_s, best_labels = None, -2, None
    cand = range(kmin, kmax + 1)
    for k in cand:
        km = KMeans(n_clusters=k, random_state=RNG, n_init=4).fit(Xs)
        labs = km.labels_
        if len(set(labs)) < 2:
            continue
        try:
            s = silhouette_score(Xs[sub] if n > 2500 else Xs, labs[sub] if n > 2500 else labs)
        except Exception:
            s = -2
        # mild preference for balance: penalize size CV
        sizes = np.bincount(labs)
        cv = sizes.std() / max(sizes.mean(), 1e-9)
        s_adj = s - 0.10 * cv
        if s_adj > best_s:
            best_s, best_k = s_adj, k
    return best_k

def cluster(idx, K):
    km = KMeans(n_clusters=K, random_state=RNG, n_init=6).fit(X[idx])
    groups = defaultdict(list)
    for it, lab in zip(idx, km.labels_):
        groups[lab].append(it)
    return list(groups.values())

def name_children(child_members, level, ancestor_words):
    """Discriminative naming across siblings. Returns list of word-lists aligned to child_members."""
    tok_sets = [node_tokens(m, level) for m in child_members]
    cov = [coverage_map(ts)[0] for ts in tok_sets]
    names = []
    for ci, members in enumerate(child_members):
        local = cov[ci]
        # candidate words: not ancestor, not stop, local coverage > 0
        cands = []
        for w, lc in local.items():
            if w in ancestor_words or w in STOP:
                continue
            other = max((cov[cj].get(w, 0.0) for cj in range(len(child_members)) if cj != ci), default=0.0)
            disc = lc - other
            cands.append((w, lc, disc))
        # prefer distinctive (disc>0), high local coverage
        distinctive = [c for c in cands if c[2] > 0.0]
        distinctive.sort(key=lambda t: (t[2], t[1]), reverse=True)
        shared = [c for c in cands if c[2] <= 0.0]
        shared.sort(key=lambda t: t[1], reverse=True)
        order = distinctive + shared
        chosen = []
        for w, lc, disc in order:
            if len(chosen) >= 5:
                break
            chosen.append(w)
            if union_coverage(tok_sets[ci], chosen) >= COVER_TARGET and len(chosen) >= 1:
                # keep adding only if still under target; stop once reached
                break
        if not chosen and order:
            chosen = [order[0][0]]
        if not chosen:
            chosen = ["category"]
        names.append(chosen)
    # repair sibling overlap (<30% jaccard) and duplicate name strings
    names = repair_siblings(names, tok_sets, cov, ancestor_words)
    return names

def jaccard(a, b):
    a, b = set(a), set(b)
    if not a or not b:
        return 0.0
    return len(a & b) / len(a | b)

def repair_siblings(names, tok_sets, cov, ancestor_words):
    n = len(names)
    for _ in range(3):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                if jaccard(names[i], names[j]) >= 0.30 or fmt_name(names[i]) == fmt_name(names[j]):
                    # try to diversify the one with more headroom (j): add a distinctive word not shared
                    target = j
                    local = cov[target]
                    used = set(names[i]) | set(names[j])
                    alt = None
                    best = -1
                    for w, lc in local.items():
                        if w in ancestor_words or w in STOP or w in used:
                            continue
                        other = max((cov[k].get(w, 0.0) for k in range(n) if k != target), default=0.0)
                        disc = lc - other
                        score = disc + 0.3 * lc
                        if score > best:
                            best, alt = score, w
                    if alt is not None:
                        # drop a shared word from target, add alt
                        shared_words = [w for w in names[target] if w in set(names[i])]
                        if shared_words and len(names[target]) > 1:
                            names[target] = [w for w in names[target] if w != shared_words[0]]
                        if alt not in names[target] and len(names[target]) < 5:
                            names[target] = names[target] + [alt]
                        changed = True
        if not changed:
            break
    return names

# ---- build tree ----
unified = [["", "", "", "", ""] for _ in range(N)]
node_records = []  # (level, name_words, ancestor_words tuple, members) for metrics

def build(idx, level, ancestor_words):
    if level > 5 or len(idx) == 0:
        return
    if level > 1 and len(idx) < MIN_SPLIT:
        return
    K = choose_K(idx, level)
    if K is None or K < (10 if level == 1 else 3):
        return
    child_members = cluster(idx, K)
    child_members = [c for c in child_members if c]
    names = name_children(child_members, level, ancestor_words)
    for members, words in zip(child_members, names):
        nm = fmt_name(words)
        for it in members:
            if orig_depth[it] >= level:
                unified[it][level - 1] = nm
        node_records.append((level, nm, tuple(sorted(ancestor_words)), len(members)))
        build(members, level + 1, ancestor_words | set(words))

print("building taxonomy...")
build(np.arange(N), 1, set())

# attach unified levels to data
for l in range(5):
    data[f"unified_level_{l+1}"] = [u[l] for u in unified]
data["depth"] = [sum(1 for x in u if x) for u in unified]

data.to_pickle("/root/work/data_built.pkl")
with open("/root/work/node_records.pkl", "wb") as f:
    pickle.dump(node_records, f)
print("done. depth dist of assigned unified nodes:")
print(data["depth"].value_counts().sort_index())
print("L1 categories:", data["unified_level_1"].nunique())
print(data["unified_level_1"].value_counts())

