    """Discriminative naming across siblings. Returns list of word-lists aligned to child_members."""
    tok_sets = [node_tokens(m, level) for m in child_members]
    cov = [coverage_map(ts)[0] for ts in tok_sets]
    names = []
    for ci, members in enumerate(child_members):
        local = cov[ci]
        # candidate words: not ancestor, not stop, local coverage > 0
